const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
fs.mkdirSync(STATE, { recursive: true });
const token = ENV('TELEGRAM_BOT_TOKEN');
const tg = (method, body) => this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/' + method,
  body: body || {},
  json: true
});

// 1. resolve chat_id from getUpdates - works only while no webhook is set.
// Once the webhook is registered the moderation workflow self-heals chat_id
// from every incoming update instead.
let chatId = null;
try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
const info = await tg('getWebhookInfo');
const hookAlreadySet = !!(info.result && info.result.url);
if (!chatId && !hookAlreadySet) {
  const r = await tg('getUpdates', { limit: 50 });
  for (const u of (r.result || [])) {
    const m = u.message || u.edited_message || (u.callback_query && u.callback_query.message);
    if (m && m.chat && m.chat.id) chatId = m.chat.id;
  }
}
if (chatId) {
  fs.writeFileSync(STATE + '/tg.json', JSON.stringify({ chat_id: chatId, saved_at: new Date().toISOString() }));
}

// 2. point the bot webhook at the moderation callback endpoint
const base = ENV('WEBHOOK_URL').replace(/\/+$/, '');
let hook = null;
if (chatId) {
  hook = await tg('setWebhook', {
    url: base + '/webhook/tg-moderation',
    allowed_updates: ['message', 'callback_query']
  });
}

let note;
if (chatId && hook && hook.ok) note = 'chat_id saved, webhook registered';
else if (hookAlreadySet && !chatId) note = 'webhook already registered; chat_id resolves automatically on the first incoming update';
else note = 'no updates found - send /start to @shared_person_bot from your account, then run this workflow again';
return [{ json: { ok: !!chatId, chat_id: chatId, webhook_set: !!(hook && hook.ok), note: note } }];
